<script setup>
const { me } = useMe();
const { data: mine, pending, error, refresh } = await useApiFetch('/api/me/player', { key: 'overview-player', default: () => ({ player: null }) });
const { data: codeData, error: codeError, refresh: refreshCodes } = await useApiFetch('/api/codes', { key: 'overview-codes', default: () => ({ codes: [] }) });
const { data: partyData, refresh: refreshParty } = await useApiFetch('/api/me/party', { key: 'overview-party', default: () => null });
const { data: ladder, error: ladderError, refresh: refreshLadder } = await useApiFetch('/api/leaderboard', { key: 'overview-ladder', query: { track: 'ranked', per: 20 }, default: () => null });
const player = computed(() => mine.value?.player);
const linked = computed(() => Boolean(player.value?.linked));
const codes = computed(() => (codeData.value?.codes || []).filter(c => c.active));
const rounds = computed(() => (player.value?.matches || []).slice(0, 5));
const leaders = computed(() => (ladder.value?.rows || []).slice(0, 5));
const match = computed(() => partyData.value?.match);
const party = computed(() => partyData.value?.party);
const queued = computed(() => Boolean(party.value?.queuedAt));
const date = value => new Date(value).toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
let poll;
onMounted(() => { poll = setInterval(() => { refresh(); refreshCodes(); refreshParty(); }, 15000); });
onBeforeUnmount(() => clearInterval(poll));
const anon = computed(() => !me.value.user);
useSeo({ title: 'Ranked World - Competitive Gorilla Tag Ranked Codes and Elo', brandTitle: true, description: 'Ranked World is a competitive Gorilla Tag platform. Join ranked codes for your bracket, climb the Elo leaderboard, run scrims and practice against bots.' });
</script>
<template>
<main id="main" class="wrap section world-overview"><section v-if="anon" class="home-hero"><div class="home-hero__copy"><h1>Ranked Gorilla Tag</h1><p class="home-lead">Ranked World is a competitive Gorilla Tag platform. Connect your account, join a ranked code for your bracket, and every round you play moves your Elo.</p><div class="home-cta"><NuxtLink class="btn btn--brand btn--large" to="/play"><AppIcon name="play" />Start playing</NuxtLink><NuxtLink class="btn btn--large" to="/ranked">How ranking works<AppIcon name="arrowRight" /></NuxtLink></div><p class="meta">Free to play. An independent community project, not affiliated with Another Axiom.</p></div><div class="home-hero__art" aria-hidden="true"><img src="/img/logo.png" alt="" width="600" height="685" /></div></section><div v-else class="world-page-title"><div><h1>Overview</h1></div><NuxtLink class="btn btn--brand" to="/play"><AppIcon name="play" />{{ linked ? 'Find a game' : 'Start playing' }}</NuxtLink></div><div v-if="error" role="alert" class="world-error"><p>We could not load your player information.</p><button class="btn" @click="refresh">Try again</button></div><div v-if="pending" class="world-skeleton" aria-label="Loading your progress" aria-busy="true" /><ProgressIdentity v-else-if="linked && player.ranked" :player="player" /><section v-else class="world-intro"><div><h2>Connect Gorilla Tag</h2><p class="meta">Connect your account to access ranked codes and record your matches.</p><NuxtLink class="btn btn--brand" to="/play">{{ me.user ? 'Connect your account' : 'Get started' }}<AppIcon name="arrowRight" /></NuxtLink></div><div class="world-intro__art" aria-hidden="true"><img src="/img/badges/ruby_1.png" alt="" /><img src="/img/badges/sapphire.png" alt="" /></div></section><div class="world-columns"><section><div class="world-section-head"><h2>Ranked codes</h2><NuxtLink to="/play">All codes <AppIcon name="arrowRight" class="world-inline-arrow" /></NuxtLink></div><div v-if="codeError" class="world-empty" role="alert"><p>Codes are unavailable right now.</p><button class="btn" @click="refreshCodes">Try again</button></div><template v-else-if="codes.length"><div v-for="c in codes.slice(0, 3)" :key="c.code" class="world-code"><span class="world-code__icon"><AppIcon name="hash" /></span><div><strong>{{ c.code }}</strong><small>{{ c.category || codeData.bracket }} / {{ c.count || 0 }} players</small></div><RoomJoinButton :code="c.code" /></div><p class="meta">Enter a code at the computer in Gorilla Tag.</p></template><div v-else class="world-empty"><h3>{{ linked ? 'No codes open in your bracket' : 'Your bracket. Your competition.' }}</h3><p class="meta">{{ linked ? 'Codes open as players come online. Try a scrim or get a practice round in while you wait.' : 'Connect your account to see the ranked codes available to you.' }}</p><NuxtLink class="btn" :to="linked ? '/play?mode=practice' : '/play'">{{ linked ? 'Get some practice' : 'Connect your account' }}<AppIcon name="arrowRight" /></NuxtLink></div></section><section class="world-session"><h3>{{ match ? (match.code || 'Preparing your room') : queued ? 'Finding your opponents' : 'Party' }}</h3><p class="meta">{{ match ? `${match.size} / ${match.state}` : queued ? 'Your party is in the queue. Open Scrims to check its status or cancel.' : party?.members?.length > 1 ? `${party.members.length} players in your party. Ready up and find a match.` : 'Invite players to your party to start a scrim.' }}</p><NuxtLink class="btn" to="/play?mode=scrims"><AppIcon name="users" />{{ match ? 'Open match' : queued ? 'View queue' : 'Open Scrims' }}</NuxtLink></section></div><section v-if="linked" class="world-rounds"><div class="world-section-head"><h2>Recent rounds</h2><NuxtLink to="/history">Match history <AppIcon name="arrowRight" class="world-inline-arrow" /></NuxtLink></div><template v-if="rounds.length"><div v-for="(m,i) in rounds" :key="m.roundId || i" class="world-result"><span class="world-result__position">{{ m.placement + 1 }}</span><div><strong>{{ m.code }}</strong><small>{{ m.afterElo - m.delta }} to {{ m.afterElo }} Elo</small></div><span class="world-result__date meta">{{ date(m.at || m.createdAt) }}</span><span class="world-result__delta" :class="m.delta >= 0 ? 'pos' : 'neg'">{{ m.delta >= 0 ? '+' : '' }}{{ m.delta }} Elo</span></div></template><div v-else class="world-empty"><h3>No matches yet</h3><p class="meta">Your scored matches will appear here after you play.</p><NuxtLink to="/play" class="btn">Find a ranked code</NuxtLink></div></section><section v-else-if="!anon" class="world-rounds"><div class="world-section-head"><h2>The leaderboard</h2><NuxtLink to="/leaderboard">Leaderboard <AppIcon name="arrowRight" class="world-inline-arrow" /></NuxtLink></div><div v-if="ladderError" role="alert" class="world-empty"><p>We could not load the leaderboard.</p><button class="btn" @click="refreshLadder">Try again</button></div><template v-else-if="leaders.length"><NuxtLink v-for="p in leaders" :key="p.discordId" :to="`/player/${p.discordId}`" class="world-result"><span class="world-result__position">{{ p.rank }}</span><div><strong>{{ p.name }}</strong><small>{{ p.ranked.tier.name }}</small></div><span class="meta world-result__date">{{ p.ranked.rounds }} rounds</span><span class="world-result__delta">{{ num(p.ranked.elo) }} Elo</span></NuxtLink></template><div v-else class="world-empty"><h3>No ranked players yet</h3><p class="meta">The ladder fills as players finish ranked rounds.</p></div></section><section v-if="anon" class="home-explain"><h2>What you do here</h2><div class="home-grid"><article><h3>Play ranked codes</h3><p>Ranked rooms are split into four brackets and you get the codes for yours, so you are playing people around your own level instead of whoever happens to be in a public lobby. Enter the code at the computer in Gorilla Tag and the round gets scored.</p></article><article><h3>Move your Elo</h3><p>Every tag is worth points, and how many depends on the Elo of the player you tagged. Those points become an Elo change when the round ends, and your Elo puts you in one of 15 divisions across the four brackets.</p></article><article><h3>Run scrims</h3><p>Make a party, queue as a team, and a bot joins the room to referee and keep score. Scrims run on their own rating, so a rough night in a scrim never touches your ranked Elo.</p></article><article><h3>Practice against a bot</h3><p>Nobody online in your bracket yet? Start a practice room against a bot from the website and warm up while you wait. Free accounts get one a day.</p></article><article><h3>Watch your replays</h3><p>Scrims record how you actually moved, if you give permission for it. A Plus or Pro membership turns those recordings into replays you can play back, next to the movement stats behind your rounds.</p></article><article><h3>Climb the leaderboard</h3><p>The ladder is public. Sort it by Elo, peak Elo, wins, tags, win streak or time survived, and filter it down to a single bracket. Every connected player gets a profile and a card they can restyle.</p><NuxtLink to="/leaderboard">See the ladder <AppIcon name="arrowRight" class="world-inline-arrow" /></NuxtLink></article></div><div class="home-why"><h2>Why it exists</h2><p>Most of a Gorilla Tag night disappears. You play well for two hours, the lobby resets, and none of it followed you anywhere. Ranked World keeps the record: rounds played in a ranked code are scored, your Elo moves, and the ladder says where you actually stand against everyone else who connected.</p><p>If you are into the comp side of Gorilla Tag, this is the part that remembers. There is a Windows launcher if you play on Steam, and Quest players enter codes inside Gorilla Tag the normal way.</p><NuxtLink class="btn btn--brand" to="/play">Connect your account<AppIcon name="arrowRight" /></NuxtLink></div></section></main>
</template>
